const r = $input.first()?.json;
const sess = $('Decode JWT + Body').first().json;
if (!r || !r.id) {
  return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe o sin acceso por RLS' } }];
}

const photosBlock = sess.photos_urls.length
  ? `\nFOTOS APORTADAS POR EL ARQUITECTO:\n${sess.photos_urls.map((u,i) => `${i+1}. ${u}`).join('\n')}\n(NOTA: no puedes ver las fotos en V1, asume que el arquitecto las ha revisado y describe lo que se ve en "description".)`
  : '';

const systemPrompt = `Eres agent_incident_handler. El arquitecto reporta un imprevisto en una obra de reforma. Tu trabajo:\n1. Inferir CAUSA PROBABLE en 1-2 frases tecnicas (humedad capilar, fallo estructural, instalacion vieja, etc.).\n2. Generar EXACTAMENTE 2 opciones de solucion (opcion_a y opcion_b). Una mas ECONOMICA y otra mas COMPLETA/DEFINITIVA. Cada una con: descripcion (2-3 frases), materiales (lista corta), coste_eur (numero realista en EUR), dias (entero), ventajas (3 max), desventajas (2-3).\n3. Redactar BORRADOR de comunicacion al cliente: profesional, claro, sin alarmismo. 100-150 palabras. Tono: explicar el imprevisto, presentar las 2 opciones, pedir decision.\n\nREGLAS:\n- Devuelve SOLO JSON valido con la forma EXACTA: { causa_probable: string, options: [{descripcion, materiales:[string], coste_eur:number, dias:number, ventajas:[string], desventajas:[string]}], comunicacion_cliente_draft: string }.\n- options DEBE tener exactamente 2 elementos: [0]=economica, [1]=completa.\n- coste_eur en EUR Espana, realista para reforma (no inventes cifras absurdas).\n- NO uses tecnicismos excesivos en comunicacion_cliente_draft.\n- Decision final es del cliente + arquitecto. Tu solo propones.`;

const userPrompt = `PROYECTO:\n- Nombre: ${r.name}\n- Direccion: ${r.location_address || '?'}, ${r.location_city || '?'}\n- Tipologia: ${r.property_type || r.project_type || '?'}, ${r.property_area_m2 || '?'} m2\n- Fase actual: ${r.current_phase}\n- Presupuesto vigente: ${r.cost_baseline_eur ? r.cost_baseline_eur + ' EUR (v' + r.cost_version + ')' : '(no calculado aun)'}\n\nIMPREVISTO REPORTADO:\n- Ubicacion: ${sess.location || '(no especificada)'}\n- Severidad inicial: ${sess.severity}\n- Descripcion del arquitecto: ${sess.description}${photosBlock}\n\nGenera el JSON con causa probable, 2 opciones y borrador de comunicacion al cliente.`;

return [{ json: {
  ...sess,
  project_id: r.id,
  project_name: r.name,
  client_name: r.client_name,
  client_email: r.client_email,
  location_city: r.location_city,
  current_phase: r.current_phase,
  cost_baseline_eur: r.cost_baseline_eur,
  llm_payload: {
    model: 'gpt-4o-mini',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.3,
    max_tokens: 1400,
    response_format: { type: 'json_object' }
  }
}}];

