const llm = $input.first()?.json;
const ctx = $('Build Prompt').first().json;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message } }];
}
const causa = String(parsed.causa_probable || '').trim();
const options = Array.isArray(parsed.options) ? parsed.options.slice(0, 4) : [];
if (options.length < 2) {
  return [{ json: { _error: 'LLM_INSUFFICIENT_OPTIONS', _status: 502, _details: 'LLM devolvio menos de 2 opciones' } }];
}
// Sanea cada opcion
const clean = options.slice(0, 2).map(o => ({
  descripcion: String(o.descripcion || '').slice(0, 800),
  materiales: Array.isArray(o.materiales) ? o.materiales.slice(0, 12).map(String) : [],
  coste_eur: Number(o.coste_eur) || 0,
  dias: Math.max(0, Math.round(Number(o.dias) || 0)),
  ventajas: Array.isArray(o.ventajas) ? o.ventajas.slice(0, 5).map(String) : [],
  desventajas: Array.isArray(o.desventajas) ? o.desventajas.slice(0, 5).map(String) : []
}));
const comunicacion = String(parsed.comunicacion_cliente_draft || '').trim();
if (!comunicacion || comunicacion.length < 50) {
  return [{ json: { _error: 'LLM_NO_COMMUNICATION', _status: 502, _details: 'borrador comunicacion cliente vacio' } }];
}
const usage = llm?.usage || {};
return [{ json: {
  ...ctx,
  causa_probable: causa,
  options: clean,
  comunicacion_cliente_draft: comunicacion,
  model: llm?.model || 'gpt-4o-mini',
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0
}}];

